class ConfSubordinacion extends BaseConfSubordinacion {

   /**
     * Obtener la conf de la subordinacion nominal dado el identificador.
     * 
     * @param $idconfsubordinacion        		Identificador del obj.
     * @return ConfSubordinacion   	            Objeto de la configuracion (clase del dominio).
     */
    public static function obtenerObjConfSubordinacionDadoId($idconfsubordinacion) {
        return Doctrine::getTable('ConfSubordinacion')->find($idconfsubordinacion);
    }
	
	public static function obtenerListadoSubordinados($idjefe) {
        
        //Devolviendo el listado de subordinados.
        return Doctrine_Query::create()
                ->from('ConfSubordinacion')
                ->where("idjefe = ?", array($idjefe))
                ->fetchArray();
	}
	
	public static function obtenerCargosSubordinado($idjefe){
	
	        //Devolviendo el listado de subordinados.
            return Doctrine_Query::create()
                ->select('idsubordinado')
                ->from('ConfSubordinacion')
                ->where("idjefe = ?", array($idjefe))
                ->fetchArray();
	
	}
	
	public static function existeSubordinado($idjefe, $idsubordinado) {
        
        //Devolviendo el listado de subordinados.
        return Doctrine_Query::create()
                ->select('count(idsubordinacion) as cantidad')
                ->from('ConfSubordinacion')
                ->where("idjefe = ? and idsubordinado=?", array($idjefe, $idsubordinado))
                ->fetchOne()
                ->cantidad;
	}
}
